INSERT INTO actividad (id, nombre, descripcion, tipo_actividad_id, instructor_id, precio, ubicacion, photo_tint, latitud, longitud, duracion_min, nivel_intensidad_id, created_at, updated_at) VALUES ('c58729e5-6bb6-5a58-8d8d-75c1f35d1ba5', 'Pesas para principiantes', 'Aprendé la técnica de los ejercicios básicos con mancuernas y barra, con cargas que se ajustan a tu nivel. Grupos chicos para poder corregir a cada uno.', '014f1324-5ace-58e4-bfa4-7ab6596fbf82', '596d9f00-2c3d-59bd-9923-33c0efe25bf3', 9000, 'Gimnasio al aire libre del Parque General San Martín, Mendoza', 'linear-gradient(135deg,#1B3A5C,#12B5A5)', -32.8905, -68.874, 60, (SELECT id FROM nivel_intensidad WHERE nombre = 'Física media' AND deleted = false), now() - interval '90 days', now() - interval '90 days');
INSERT INTO actividad (id, nombre, descripcion, tipo_actividad_id, instructor_id, precio, ubicacion, photo_tint, latitud, longitud, duracion_min, nivel_intensidad_id, created_at, updated_at) VALUES ('c28f22df-e5a3-5c16-a913-d8ab1858d966', 'Tonificación con cargas livianas', 'Circuito suave con bandas elásticas y mancuernas livianas para ganar fuerza y mejorar la postura. Ideal para retomar la actividad física.', '03f72005-bd77-5d0c-9f7f-8251356a2e24', '596d9f00-2c3d-59bd-9923-33c0efe25bf3', 7000, 'Plaza España, Ciudad de Mendoza', 'linear-gradient(135deg,#22543D,#12B5A5)', -32.8939, -68.8414, 50, (SELECT id FROM nivel_intensidad WHERE nombre = 'Física baja' AND deleted = false), now() - interval '89 days', now() - interval '89 days');
INSERT INTO actividad (id, nombre, descripcion, tipo_actividad_id, instructor_id, precio, ubicacion, photo_tint, latitud, longitud, duracion_min, nivel_intensidad_id, created_at, updated_at) VALUES ('e6900528-42a8-5586-b013-54b2a0d637c5', 'Funcional en el parque', 'Entrenamiento funcional al aire libre: movimientos de la vida diaria, coordinación y equilibrio. Cada ejercicio tiene una versión más simple y una más exigente.', '3e9e7ebc-dc55-5756-9fbb-23f437387210', '596d9f00-2c3d-59bd-9923-33c0efe25bf3', 8000, 'Rosedal del Parque General San Martín, Mendoza', 'linear-gradient(135deg,#173250,#0FB8A9)', -32.8925, -68.868, 60, (SELECT id FROM nivel_intensidad WHERE nombre = 'Física media' AND deleted = false), now() - interval '88 days', now() - interval '88 days');
INSERT INTO actividad (id, nombre, descripcion, tipo_actividad_id, instructor_id, precio, ubicacion, photo_tint, latitud, longitud, duracion_min, nivel_intensidad_id, created_at, updated_at) VALUES ('0e5067eb-c8bb-5b45-adb5-f87bacdf8ba9', 'Defensa personal para el día a día', 'Técnicas simples de prevención y de respuesta ante situaciones de riesgo, practicadas con cuidado y sin contacto fuerte. No hace falta experiencia previa.', '6cbc6bb3-4d50-5a49-bc56-9ff22135f75a', '596d9f00-2c3d-59bd-9923-33c0efe25bf3', 8500, 'Polideportivo municipal, Godoy Cruz', 'linear-gradient(135deg,#0E2A47,#7A52D9)', -32.925, -68.844, 75, (SELECT id FROM nivel_intensidad WHERE nombre = 'Física media' AND deleted = false), now() - interval '87 days', now() - interval '87 days');
INSERT INTO actividad (id, nombre, descripcion, tipo_actividad_id, instructor_id, precio, ubicacion, photo_tint, latitud, longitud, duracion_min, nivel_intensidad_id, created_at, updated_at) VALUES ('33f938b1-b671-5a49-98d2-78132a9ebc9c', 'Running recreativo en grupo', 'Salidas a correr en grupo alrededor del lago, alternando trote y caminata. Cada persona va a su ritmo: lo importante es sumar kilómetros y pasarla bien.', 'e6b792d5-5b2d-5db9-a185-ad17d66a937e', '5fa64670-a70e-503d-bc5c-168ffb9825c9', 6000, 'Lago del Parque General San Martín, Mendoza', 'linear-gradient(135deg,#1B3A5C,#12B5A5)', -32.888, -68.881, 60, (SELECT id FROM nivel_intensidad WHERE nombre = 'Física media' AND deleted = false), now() - interval '86 days', now() - interval '86 days');
INSERT INTO actividad (id, nombre, descripcion, tipo_actividad_id, instructor_id, precio, ubicacion, photo_tint, latitud, longitud, duracion_min, nivel_intensidad_id, created_at, updated_at) VALUES ('9d876634-1a62-5259-bf36-5949abd7fc76', 'Bicicleteada por los caminos de Maipú', 'Paseo en bicicleta por caminos rurales entre viñedos, a ritmo tranquilo y con paradas. Se puede ir con bicicleta propia; el recorrido es casi todo llano.', 'd3056bed-74e1-51a4-87d7-f237e3565e7a', '5fa64670-a70e-503d-bc5c-168ffb9825c9', 9500, 'Plaza departamental de Maipú, Mendoza', 'linear-gradient(135deg,#22543D,#12B5A5)', -32.983, -68.786, 120, (SELECT id FROM nivel_intensidad WHERE nombre = 'Física media' AND deleted = false), now() - interval '85 days', now() - interval '85 days');
INSERT INTO actividad (id, nombre, descripcion, tipo_actividad_id, instructor_id, precio, ubicacion, photo_tint, latitud, longitud, duracion_min, nivel_intensidad_id, created_at, updated_at) VALUES ('507b52cb-3d82-518d-b768-c709191c2050', 'Resistencia con el propio cuerpo', 'Sentadillas, flexiones, planchas y saltos en series cortas. Es la clase más intensa de la semana, con pausas para recuperar el aire.', 'e6a18dd5-6010-52fc-b5f0-6cebb9b5a190', '5fa64670-a70e-503d-bc5c-168ffb9825c9', 7500, 'Parque Central, Ciudad de Mendoza', 'linear-gradient(135deg,#173250,#0FB8A9)', -32.879, -68.838, 60, (SELECT id FROM nivel_intensidad WHERE nombre = 'Física alta' AND deleted = false), now() - interval '84 days', now() - interval '84 days');
INSERT INTO actividad (id, nombre, descripcion, tipo_actividad_id, instructor_id, precio, ubicacion, photo_tint, latitud, longitud, duracion_min, nivel_intensidad_id, created_at, updated_at) VALUES ('5788b9a9-ff10-57ce-bca4-e2b010568134', 'Yoga al amanecer', 'Secuencias suaves de yoga para empezar el día con energía: respiración, posturas básicas y un momento final de relajación. Traé tu mat.', '90ffd691-145c-57c3-93b6-ca2950cd83ff', 'c460ee33-a22f-5caa-b13e-456647b0b2ab', 7000, 'Plaza de Chacras de Coria, Luján de Cuyo', 'linear-gradient(135deg,#0E2A47,#7A52D9)', -32.989, -68.874, 60, (SELECT id FROM nivel_intensidad WHERE nombre = 'Física baja' AND deleted = false), now() - interval '83 days', now() - interval '83 days');
INSERT INTO actividad (id, nombre, descripcion, tipo_actividad_id, instructor_id, precio, ubicacion, photo_tint, latitud, longitud, duracion_min, nivel_intensidad_id, created_at, updated_at) VALUES ('0584fb9a-5012-543e-a187-5f1f1ac87496', 'Pilates en colchoneta', 'Pilates mat para fortalecer el centro del cuerpo, mejorar la postura y ganar flexibilidad. Ejercicios controlados, apto para todo público.', '546d8bcb-729e-52f2-9861-edee709a9995', 'c460ee33-a22f-5caa-b13e-456647b0b2ab', 8000, 'Sala de usos múltiples del Centro Cultural, Ciudad de Mendoza', 'linear-gradient(135deg,#1B3A5C,#12B5A5)', -32.887, -68.845, 55, (SELECT id FROM nivel_intensidad WHERE nombre = 'Física baja' AND deleted = false), now() - interval '82 days', now() - interval '82 days');
INSERT INTO actividad (id, nombre, descripcion, tipo_actividad_id, instructor_id, precio, ubicacion, photo_tint, latitud, longitud, duracion_min, nivel_intensidad_id, created_at, updated_at) VALUES ('ac55d55d-ac64-58c1-859b-78757ff7ec12', 'Estiramientos y movilidad', 'Una clase corta para soltar tensiones de la semana: estiramientos guiados y ejercicios de movilidad articular. Ideal para complementar otra actividad.', 'f10fc06f-484a-5d6c-b585-1b1792dfcdcb', 'c460ee33-a22f-5caa-b13e-456647b0b2ab', 5500, 'Sala de usos múltiples del Centro Cultural, Ciudad de Mendoza', 'linear-gradient(135deg,#22543D,#12B5A5)', -32.887, -68.845, 45, (SELECT id FROM nivel_intensidad WHERE nombre = 'Física baja' AND deleted = false), now() - interval '81 days', now() - interval '81 days');
INSERT INTO actividad (id, nombre, descripcion, tipo_actividad_id, instructor_id, precio, ubicacion, photo_tint, latitud, longitud, duracion_min, nivel_intensidad_id, created_at, updated_at) VALUES ('91d8eb78-95f0-51b1-a58d-0f99c9850d4a', 'Relajación y respiración consciente', 'Técnicas de respiración y relajación guiada para bajar el estrés. Se practica sentado o acostado, sin exigencia física.', '7838df4a-38fe-5bfc-a791-d1157eca1cdb', 'c460ee33-a22f-5caa-b13e-456647b0b2ab', 5000, 'Plaza de Chacras de Coria, Luján de Cuyo', 'linear-gradient(135deg,#173250,#0FB8A9)', -32.989, -68.874, 60, (SELECT id FROM nivel_intensidad WHERE nombre = 'Física baja' AND deleted = false), now() - interval '80 days', now() - interval '80 days');
INSERT INTO actividad (id, nombre, descripcion, tipo_actividad_id, instructor_id, precio, ubicacion, photo_tint, latitud, longitud, duracion_min, nivel_intensidad_id, created_at, updated_at) VALUES ('c58e1ed2-058d-5bec-bbc7-d835bc3a1bbe', 'Senderismo al Cerro Arco', 'Caminata por senderos marcados hasta el mirador, con vista a toda la ciudad. Se avanza a ritmo de grupo y con paradas para hidratarse.', '20de3019-dc80-5afb-aa29-37e09ee15c2a', 'df00605d-94f7-57f5-9952-e063ec27de97', 10000, 'Base del Cerro Arco, El Challao, Las Heras', 'linear-gradient(135deg,#0E2A47,#7A52D9)', -32.858, -68.893, 180, (SELECT id FROM nivel_intensidad WHERE nombre = 'Física media' AND deleted = false), now() - interval '79 days', now() - interval '79 days');
INSERT INTO actividad (id, nombre, descripcion, tipo_actividad_id, instructor_id, precio, ubicacion, photo_tint, latitud, longitud, duracion_min, nivel_intensidad_id, created_at, updated_at) VALUES ('8b96a5f2-ca62-5f5b-b837-933576295a17', 'Trekking en Potrerillos', 'Jornada de trekking por quebradas y lomas de la precordillera. Requiere buena condición física y calzado de montaña; incluye charla de seguridad antes de salir.', 'aa5fec70-af0a-58ff-b485-8688065f5252', 'df00605d-94f7-57f5-9952-e063ec27de97', 18000, 'Villa de Potrerillos, Luján de Cuyo', 'linear-gradient(135deg,#1B3A5C,#12B5A5)', -32.96, -69.196, 300, (SELECT id FROM nivel_intensidad WHERE nombre = 'Física alta' AND deleted = false), now() - interval '78 days', now() - interval '78 days');
INSERT INTO actividad (id, nombre, descripcion, tipo_actividad_id, instructor_id, precio, ubicacion, photo_tint, latitud, longitud, duracion_min, nivel_intensidad_id, created_at, updated_at) VALUES ('5b9dba97-66d3-5cf1-bd06-401aaf6999f4', 'Mountain bike en El Challao', 'Recorrido en mountain bike por senderos de tierra con subidas y bajadas. Se repasa la técnica de frenado y manejo antes de cada tramo.', 'f2992824-d846-5d7b-b843-5657b795b116', 'df00605d-94f7-57f5-9952-e063ec27de97', 12000, 'Parque de El Challao, Las Heras', 'linear-gradient(135deg,#22543D,#12B5A5)', -32.862, -68.879, 150, (SELECT id FROM nivel_intensidad WHERE nombre = 'Física alta' AND deleted = false), now() - interval '77 days', now() - interval '77 days');
INSERT INTO actividad (id, nombre, descripcion, tipo_actividad_id, instructor_id, precio, ubicacion, photo_tint, latitud, longitud, duracion_min, nivel_intensidad_id, created_at, updated_at) VALUES ('7f397327-05ce-5b0d-8f0d-bcc16955a15c', 'Escalada para principiantes en palestra', 'Primeros pasos en escalada con arnés y cuerda, siempre asegurados por el instructor. Aprendés los nudos básicos y a moverte en la pared.', 'fbbb72d6-05f1-5d68-b23b-45eefbf00bd5', 'df00605d-94f7-57f5-9952-e063ec27de97', 11000, 'Palestra de escalada, Ciudad de Mendoza', 'linear-gradient(135deg,#173250,#0FB8A9)', -32.885, -68.84, 90, (SELECT id FROM nivel_intensidad WHERE nombre = 'Física media' AND deleted = false), now() - interval '76 days', now() - interval '76 days');
INSERT INTO actividad (id, nombre, descripcion, tipo_actividad_id, instructor_id, precio, ubicacion, photo_tint, latitud, longitud, duracion_min, nivel_intensidad_id, created_at, updated_at) VALUES ('c060adfd-1ded-57e7-bee9-56c040e3f280', 'Natación para adultos', 'Clases para mejorar la técnica de crol y espalda, con ejercicios por niveles dentro de la misma pileta. Para quienes ya flotan y quieren nadar mejor.', '70a240b8-2fd3-5b6b-b17c-84055040943f', '3f289400-b6e1-59fd-a37c-c9f3aec9469f', 9000, 'Pileta climatizada municipal, Godoy Cruz', 'linear-gradient(135deg,#0E2A47,#7A52D9)', -32.927, -68.85, 50, (SELECT id FROM nivel_intensidad WHERE nombre = 'Física media' AND deleted = false), now() - interval '75 days', now() - interval '75 days');
INSERT INTO actividad (id, nombre, descripcion, tipo_actividad_id, instructor_id, precio, ubicacion, photo_tint, latitud, longitud, duracion_min, nivel_intensidad_id, created_at, updated_at) VALUES ('9e4ee5ff-c475-5d8c-905b-66f6cc3f4240', 'Ritmos latinos para moverse', 'Una hora de baile con coreografías simples de salsa, cumbia y merengue. No hace falta pareja ni saber bailar: se aprende en el momento.', '73edeea9-911b-547c-9ef6-7c10ecf91d45', '3f289400-b6e1-59fd-a37c-c9f3aec9469f', 6500, 'Salón de la Casa de la Cultura, Godoy Cruz', 'linear-gradient(135deg,#1B3A5C,#12B5A5)', -32.926, -68.845, 60, (SELECT id FROM nivel_intensidad WHERE nombre = 'Física media' AND deleted = false), now() - interval '74 days', now() - interval '74 days');
INSERT INTO actividad (id, nombre, descripcion, tipo_actividad_id, instructor_id, precio, ubicacion, photo_tint, latitud, longitud, duracion_min, nivel_intensidad_id, created_at, updated_at) VALUES ('b56c68c2-fb1a-5ebe-ab45-5813e797bba6', 'Tai Chi en la plaza', 'Movimientos lentos y coordinados con la respiración, al aire libre. Mejora el equilibrio y la concentración; apto para todas las edades.', '33c1043d-69ed-5c27-8eab-1154c91748da', '3f289400-b6e1-59fd-a37c-c9f3aec9469f', 5000, 'Plaza Independencia, Ciudad de Mendoza', 'linear-gradient(135deg,#22543D,#12B5A5)', -32.8894, -68.8458, 60, (SELECT id FROM nivel_intensidad WHERE nombre = 'Física baja' AND deleted = false), now() - interval '73 days', now() - interval '73 days');
